BEGIN;
SET LOCAL lock_timeout = '5s';
DO $$ BEGIN IF current_database() <> 'rag_linebot' THEN RAISE EXCEPTION 'Wrong database'; END IF; END $$;
CREATE TABLE IF NOT EXISTS rag_v2.leaflet_source_catalog (
  license_no text NOT NULL,
  document_type text NOT NULL CHECK (document_type IN ('leaflet','label')),
  url text NOT NULL,
  imported_from text NOT NULL,
  imported_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (license_no, document_type, url)
);
