INSERT INTO rag_v2.drug_master (license_no,name_zh,name_en,source_url,source_version)
SELECT license_no,name_zh,name_en,leaflet_urls->>0,'attachment:73d89c21ec218468' FROM fda_import
WHERE jsonb_array_length(leaflet_urls)>0
ON CONFLICT (license_no) DO NOTHING;
INSERT INTO rag_v2.leaflet_source_catalog (license_no,document_type,url,imported_from)
SELECT i.license_no,a.document_type,u.url,'attachment:73d89c21ec218468'
FROM fda_import i
CROSS JOIN LATERAL (VALUES ('leaflet',i.leaflet_urls),('label',i.label_urls)) a(document_type, urls)
CROSS JOIN LATERAL jsonb_array_elements_text(a.urls) u(url)
ON CONFLICT (license_no,document_type,url) DO NOTHING;
WITH candidates AS (
 SELECT i.license_no, v.drug_id, v.leaflet_version,
        i.leaflet_urls->>0 AS url, count(*) OVER (PARTITION BY i.license_no) AS candidates
 FROM fda_import i JOIN rag_v2.current_leaflet_versions v
 ON rag_v2.identity_key(v.license_no)=rag_v2.identity_key(i.license_no)
 WHERE jsonb_array_length(i.leaflet_urls)>0
)
INSERT INTO rag_v2.leaflet_links (drug_id,license_no,leaflet_version,verified,evidence)
SELECT drug_id,license_no,leaflet_version,false,url FROM candidates WHERE candidates=1
ON CONFLICT (drug_id) DO NOTHING;
SELECT count(*) AS supplied, count(*) FILTER (WHERE n=0) AS no_leaflet,
       count(*) FILTER (WHERE n=1) AS unique_candidate, count(*) FILTER (WHERE n>1) AS multiple,
       (SELECT count(*) FROM rag_v2.leaflet_source_catalog WHERE imported_from='attachment:73d89c21ec218468' AND document_type='leaflet') AS leaflet_urls,
       (SELECT count(*) FROM rag_v2.leaflet_source_catalog WHERE imported_from='attachment:73d89c21ec218468' AND document_type='label') AS label_urls
FROM (
 SELECT i.license_no,count(v.drug_id) AS n
 FROM fda_import i LEFT JOIN rag_v2.current_leaflet_versions v
 ON rag_v2.identity_key(v.license_no)=rag_v2.identity_key(i.license_no)
 GROUP BY i.license_no
) stats;
COMMIT;
SELECT count(DISTINCT license_no) AS licenses,
 count(*) FILTER (WHERE document_type='leaflet') AS leaflet_urls,
 count(*) FILTER (WHERE document_type='label') AS label_urls,
 (SELECT count(*) FROM rag_v2.drug_master WHERE source_version='attachment:73d89c21ec218468') AS new_master,
 (SELECT count(*) FROM rag_v2.leaflet_links WHERE NOT verified) AS pending_links
FROM rag_v2.leaflet_source_catalog WHERE imported_from='attachment:73d89c21ec218468';
